// =====================================================================
// v21 : ICÔNES D'OBJETS VARIÉES (enveloppe itemIcon)
// Vêtements : mini dessin de la forme portée (vMiniIcon, 01_draw_chars.js).
// Autres objets : pictogramme choisi par MOTS-CLÉS du nom (ICO_RULES), sinon l'icône d'avant.
// La couleur de l'objet (it.color) colore le pictogramme ; un liseré fin suit la rareté.
// =====================================================================
const IL = '#5b4636';
const ist = (w = 1.6) => `stroke="${IL}" stroke-width="${w}" stroke-linejoin="round" stroke-linecap="round"`;
const iP = (d, f, w) => `<path d="${d}" fill="${f}" ${ist(w)}/>`;
const iC = (x, y, r, f, w) => `<circle cx="${x}" cy="${y}" r="${r}" fill="${f}" ${ist(w)}/>`;
const iE = (x, y, rx, ry, f, w) => `<ellipse cx="${x}" cy="${y}" rx="${rx}" ry="${ry}" fill="${f}" ${ist(w)}/>`;
const iR = (x, y, w, h, r, f, sw) => `<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${r}" fill="${f}" ${ist(sw)}/>`;
const iL = (d, c = IL, w = 1.3) => `<path d="${d}" fill="none" stroke="${c}" stroke-width="${w}" stroke-linecap="round" stroke-linejoin="round"/>`;
const iH = (x, y, r = 2) => `<ellipse cx="${x}" cy="${y}" rx="${r}" ry="${r * 1.4}" fill="#fff" opacity=".7"/>`;
const iLeaf = (x, y, rot, c = '#7fbf5f', s = 1) => `<path d="M0 0 q${4 * s} ${-6 * s} ${10 * s} ${-4 * s} q${-3 * s} ${6 * s} ${-10 * s} ${4 * s}Z" fill="${c}" ${ist(1.2)} transform="translate(${x} ${y}) rotate(${rot})"/>`;
const iStar = (x, y, r, f) => `<path d="${starD(x, y, r)}" fill="${f}" ${ist(1.3)}/>`;
const iPet = (x, y, r, n, c, mid) => Array.from({ length: n }, (_, k) => { const a = k * 2 * Math.PI / n - 1.57; return iC((x + Math.cos(a) * r).toFixed(1), (y + Math.sin(a) * r).toFixed(1), (r * 0.78).toFixed(1), c, 1.1); }).join('') + iC(x, y, (r * 0.6).toFixed(1), mid || '#f2c14e', 1.1);
const iJar = (c, lid) => iR(9, 12, 22, 24, 6, '#fffaf2') + iR(11, 18, 18, 16, 4, c, 1.1) + iR(8, 6, 24, 7, 2.5, lid || '#e5584f') + iH(14, 22);
const iCup = c => iP('M8 14 H28 V25 C28 34 8 34 8 25Z', '#fffaf2') + iP('M10 16 H26 V21 H10Z', c, 1) + iL('M28 18 h3 a3.5 3.5 0 0 1 0 7 h-3', IL, 1.6) + iL('M14 5 q3 3 0 6 M20 5 q3 3 0 6', IL, 1.2);

